/* StudySpark AI Coach â€” browser-only prototype. All data is stored locally. */
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const DB_KEY = 'studyspark_data_v1';
const SESSION_KEY = 'studyspark_session_v1';
const GUEST_KEY = 'studyspark_guest_data_v1';
const GUEST_SESSION = '__guest__';
const FALLBACK_COURSES = ['English','Math','Biology','Chemistry','Physics','Science','History','Geography','Business','Computer Science','French','Art','Music','Health'];
const SYSTEM_FOLDER_ID = 'uncategorized';
const appData = {courses:[],plannerTemplates:null};
const FALLBACK_PLANNER_TEMPLATES = {fallback:{keywords:[],taskTypes:['concept review','practice set','mistake correction'],practiceTypes:['focused questions','mixed practice','teach-back check'],reviewTypes:['mistake review','summary recall'],studyTasks:['Study {topic} by reading the clearest notes and writing a short summary.'],stepTasks:['List what you know, study one example, then explain {topic} without looking.'],practiceTasks:['Complete {practiceCount} focused questions about {topic}, then check every answer.'],mistakeChecks:['Correct each mistake and write the reason the correct answer works.'],miniReviews:['Make three quick flashcards or recall prompts for {topic}.']}};

const sampleNotes = [
  {id:'sample-bio',subject:'Biology',title:'Cell structure and function',text:'Cells are the basic unit of life. The cell membrane controls what enters and leaves the cell. The nucleus stores DNA and directs cell activities. Mitochondria release energy through cellular respiration. Ribosomes build proteins. Plant cells also have chloroplasts for photosynthesis and a rigid cell wall.',created:'Sample'},
  {id:'sample-math',subject:'Mathematics',title:'Quadratic equations',text:'A quadratic equation has the form ax squared plus bx plus c equals zero. It can be solved by factoring, completing the square, or using the quadratic formula. The discriminant b squared minus 4ac tells us how many real solutions exist. A positive discriminant gives two real solutions.',created:'Sample'},
  {id:'sample-eng',subject:'English',title:'Literary analysis essentials',text:'A strong literary analysis uses a clear thesis supported by evidence from the text. Theme is the central idea explored by a work. Tone reflects the authorâ€™s attitude, while mood is the feeling created for the reader. Explain how each quotation supports the argument instead of only summarizing it.',created:'Sample'}
];

// Build reusable multi-select course controls and folder selectors. The default available courses come from JSON; custom courses are saved per user in localStorage.
function normalizeCourseName(name=''){return name.trim().replace(/\s+/g,' ')}
function limitCourseName(name=''){return normalizeCourseName(name).slice(0,30)}
function uniqueCourses(list=[]){const seen=new Set();return list.map(limitCourseName).map(s=>s==='Mathematics'?'Math':s).filter(Boolean).filter(s=>{const key=s.toLowerCase();if(seen.has(key))return false;seen.add(key);return true})}
function customCourses(){const u=user();return uniqueCourses(u?.customCourses||[])}
function availableCourses(){return uniqueCourses([...appData.courses,...customCourses()])}
function courseExists(name,extra=[]){const key=normalizeCourseName(name).toLowerCase();return [...availableCourses(),...extra].some(c=>c.toLowerCase()===key)}
function courseButtons(name,selected=[],courses=availableCourses()){const custom=customCourses().map(c=>c.toLowerCase());return courses.map(c=>`<label class="course-chip ${custom.includes(c.toLowerCase())?'custom-chip':''}"><input type="checkbox" name="${name}" value="${escapeHTML(c)}" ${selected.includes(c)?'checked':''}><span>${escapeHTML(c)}</span></label>`).join('')}
function selectedCourses(){const u=user();return uniqueCourses(u?.courses||[]).filter(c=>availableCourses().some(a=>a.toLowerCase()===c.toLowerCase()))}
function courseOptionsHTML(courses=selectedCourses()){return courses.length?courses.map(c=>`<option value="${escapeHTML(c)}">${escapeHTML(c)}</option>`).join(''):'<option value="" disabled selected>No courses selected â€” update profile</option>'}
function renderSignupCourses(){const chosen=$$('input[name="courses"]:checked').map(x=>x.value);$('#signupCourses').innerHTML=courseButtons('courses',chosen)}
async function loadCourses(){try{const res=await fetch('data/courses.json',{cache:'no-store'});if(!res.ok)throw new Error('data/courses.json not found');const data=await res.json(),list=Array.isArray(data)?data:data.courses;if(Array.isArray(list)&&list.length)appData.courses=list}catch{appData.courses=FALLBACK_COURSES;toast('Course list could not load, so fallback courses are available.')}renderSignupCourses();if(user()){renderSettings();refreshAfterCourseChange()}}
async function loadPlannerTemplates(){try{const res=await fetch('data/plannerTemplates.json',{cache:'no-store'});if(!res.ok)throw new Error('plannerTemplates.json not found');const data=await res.json();appData.plannerTemplates=data&&data.fallback?data:FALLBACK_PLANNER_TEMPLATES}catch{appData.plannerTemplates=FALLBACK_PLANNER_TEMPLATES}}
const flashControls=$('#flashSubject').parentElement;flashControls.insertBefore(Object.assign(document.createElement('select'),{id:'flashFolder'}),$('#generateCardsBtn'));
const quizControls=$('#quizSubject').parentElement;quizControls.insertBefore(Object.assign(document.createElement('select'),{id:'quizFolder'}),$('#generateQuizBtn'));
const planInput=$('#planSubject');const planPicker=document.createElement('fieldset');planPicker.className='course-picker compact';planPicker.innerHTML='<legend>Courses <small>Select one or more</small></legend><div id="planCourses" class="course-options"></div>';planInput.closest('label').replaceWith(planPicker);const planFolderLabel=document.createElement('label');planFolderLabel.innerHTML='Folder<select id="planFolder"></select>';planPicker.after(planFolderLabel);
const organizer=document.createElement('section');organizer.className='card resource-organizer';organizer.innerHTML='<div class="card-head"><div><h3>Move study resources</h3><p>Choose a new folder for cards, quizzes, or study plans.</p></div></div><div id="resourceMoveList" class="resource-move-list"></div>';$('#dashboardFolders').after(organizer);

let db = loadDB();
let currentUser = localStorage.getItem(SESSION_KEY) || null;
let guestData = loadGuestData();
let currentCards = [], cardIndex = 0;
let activeNoteId = null, noteEditSnapshot = null;

function loadDB(){
  try{return JSON.parse(localStorage.getItem(DB_KEY)) || {users:{}}}catch{return {users:{}}}
}
function saveDB(){if(isGuestMode())localStorage.setItem(GUEST_KEY,JSON.stringify(guestData));else localStorage.setItem(DB_KEY,JSON.stringify(db))}
function user(){return isGuestMode() ? guestData : currentUser ? db.users[currentUser] : null}
function isGuestMode(){return currentUser===GUEST_SESSION}
function freshData(account){const folders=[{id:SYSTEM_FOLDER_ID,name:'Uncategorized',updated:today(),color:'#8b95aa',protected:true,parentId:''}];const notes=sampleNotes.map(n=>({...n,subject:n.subject==='Mathematics'?'Math':n.subject,folderId:SYSTEM_FOLDER_ID}));account.customCourses=uniqueCourses(account.customCourses||[]);account.courses=uniqueCourses(account.courses||account.subjects||[]);delete account.subjects;return {...account,folders,notes,flashcards:[],quizzes:[],plans:[],files:[],progress:{cardsCompleted:0,cardsKnown:0,weakTopics:[],minutes:0,streak:1,lastStudy:today()},activity:[{type:'note',text:'Sample study library added',time:'Just now'}]}}
function freshGuestData(){return {name:'Guest Student',grade:'Guest Mode',email:null,courses:[],customCourses:[],folders:[{id:SYSTEM_FOLDER_ID,name:'Uncategorized',updated:today(),color:'#8b95aa',protected:true,parentId:''}],notes:[],files:[],flashcards:[],quizzes:[],plans:[],progress:{cardsCompleted:0,cardsKnown:0,weakTopics:[],minutes:0,streak:1,lastStudy:today()},activity:[]}}
function loadGuestData(){try{return normalizeGuestData(JSON.parse(localStorage.getItem(GUEST_KEY)))}catch{return freshGuestData()}}
function normalizeGuestData(data){return data&&typeof data==='object'?{...freshGuestData(),...data,name:'Guest Student',grade:'Guest Mode',email:null}:freshGuestData()}
function isLegacySampleFolder(f){const names=[['Biology','Unit','1'].join(' '),['Math','Exam','Review'].join(' '),['English','Essays'].join(' ')],ids=['folder-biology','folder-math','folder-english','bio-unit-1','math-review','english-essays','f-bio','f-math','f-english'];return names.includes(f.name)||ids.includes(f.id)}
function migrateUser(u){u.customCourses=uniqueCourses(u.customCourses||[]);u.courses=uniqueCourses([...(u.courses||[]),...(u.subjects||[])]);u.courses.forEach(c=>{if(!appData.courses.some(d=>d.toLowerCase()===c.toLowerCase())&&!u.customCourses.some(x=>x.toLowerCase()===c.toLowerCase()))u.customCourses.push(c)});u.customCourses=uniqueCourses(u.customCourses);delete u.subjects;u.folders=u.folders||[];const legacyFolderIds=u.folders.filter(isLegacySampleFolder).map(f=>f.id);let unc=u.folders.find(f=>f.id===SYSTEM_FOLDER_ID||f.name==='Uncategorized');if(!unc){unc={id:SYSTEM_FOLDER_ID,name:'Uncategorized',updated:today(),color:'#8b95aa',protected:true,parentId:''};u.folders.unshift(unc)}else Object.assign(unc,{id:SYSTEM_FOLDER_ID,name:'Uncategorized',protected:true,parentId:''});u.folders=u.folders.filter(f=>(f.id===SYSTEM_FOLDER_ID||!f.protected)&&!legacyFolderIds.includes(f.id)).map((f,i)=>({...f,color:f.color||['#5867e8','#8b6ddd','#40a77e','#dd8b51'][i%4],parentId:f.protected?'':f.parentId||''}));u.notes=(u.notes||[]).map(n=>({...n,subject:n.subject==='Mathematics'?'Math':n.subject,folderId:legacyFolderIds.includes(n.folderId)?SYSTEM_FOLDER_ID:normalizeFolderId(n.folderId)}));u.flashcards=(u.flashcards||[]).map(c=>({...c,folderId:legacyFolderIds.includes(c.folderId)?SYSTEM_FOLDER_ID:normalizeFolderId(c.folderId)}));u.quizzes=(u.quizzes||[]).map(q=>({...q,folderId:legacyFolderIds.includes(q.folderId)?SYSTEM_FOLDER_ID:normalizeFolderId(q.folderId)}));u.plans=(u.plans||[]).map(p=>migratePlanDays({...p,courses:p.courses||[p.subject].filter(Boolean),folderId:legacyFolderIds.includes(p.folderId)?SYSTEM_FOLDER_ID:normalizeFolderId(p.folderId)}));u.files=(u.files||[]).map(f=>({...f,folderId:legacyFolderIds.includes(f.folderId)?SYSTEM_FOLDER_ID:normalizeFolderId(f.folderId)}));saveDB()}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2600)}
function escapeHTML(value=''){return String(value).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function today(){return new Date().toISOString().slice(0,10)}
function recordActivity(type,text){const u=user();u.activity.unshift({type,text,time:'Just now'});u.activity=u.activity.slice(0,12);touchStudy();saveDB()}
function touchStudy(){const p=user().progress;if(p.lastStudy!==today()){const yesterday=new Date(Date.now()-86400000).toISOString().slice(0,10);p.streak=p.lastStudy===yesterday?p.streak+1:1;p.lastStudy=today()}}

/* Authentication */
function openAuth(mode='signup'){$('#authModal').classList.add('open');$('#authModal').setAttribute('aria-hidden','false');switchAuth(mode)}
function closeAuth(){$('#authModal').classList.remove('open');$('#authModal').setAttribute('aria-hidden','true')}
function switchAuth(mode){$$('.auth-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===mode));$('#signupForm').classList.toggle('hidden',mode!=='signup');$('#loginForm').classList.toggle('hidden',mode!=='login');$('#authTitle').textContent=mode==='signup'?'Create your account':'Welcome back';$('#authSubtitle').textContent=mode==='signup'?'Start studying smarter today. It is free.':'Pick up right where you left off.'}
function confirmDialog({title='Confirm action',message='',okText='Continue',cancelText='Cancel',danger=false}){return new Promise(resolve=>{const modal=$('#confirmModal'),ok=$('#confirmOk'),cancel=$('#confirmCancel');$('#confirmTitle').textContent=title;$('#confirmMessage').textContent=message;ok.textContent=okText;cancel.textContent=cancelText;ok.className='btn '+(danger?'btn-danger':'btn-primary');modal.classList.add('open');modal.setAttribute('aria-hidden','false');const done=value=>{modal.classList.remove('open');modal.setAttribute('aria-hidden','true');ok.onclick=cancel.onclick=null;resolve(value)};ok.onclick=()=>done(true);cancel.onclick=()=>done(false)})}
$$('[data-auth]').forEach(btn=>btn.addEventListener('click',e=>{e.preventDefault();openAuth(btn.dataset.auth)}));
$$('[data-guest]').forEach(btn=>btn.addEventListener('click',e=>{e.preventDefault();enterGuestMode()}));
$$('[data-close]').forEach(btn=>btn.addEventListener('click',closeAuth));
$$('.auth-tabs button').forEach(btn=>btn.addEventListener('click',()=>switchAuth(btn.dataset.tab)));
$('#authModal').addEventListener('click',e=>{if(e.target===$('#authModal'))closeAuth()});
$('#signupForm').addEventListener('submit',async e=>{e.preventDefault();const wasGuest=isGuestMode(),guestSnapshot=wasGuest?cloneData(user()):null,fd=new FormData(e.target),email=fd.get('email').trim().toLowerCase(),courses=fd.getAll('courses');if(!courses.length&&!wasGuest)return toast('Choose at least one course.');if(db.users[email])return toast('An account with that email already exists.');db.users[email]=freshData({name:fd.get('name').trim(),email,password:fd.get('password'),grade:fd.get('grade'),courses});currentUser=null;localStorage.removeItem(SESSION_KEY);localStorage.setItem(DB_KEY,JSON.stringify(db));logIn(email);toast('Your StudySpark account is ready.');if(wasGuest&&guestSnapshot){const move=await confirmDialog({title:'Move guest data?',message:'Do you want to move your guest data into this account?',okText:'Move Guest Data',cancelText:'Start Fresh'});if(move){moveGuestDataToAccount(guestSnapshot,user());saveDB();renderAll();const clear=await confirmDialog({title:'Guest data moved',message:'Do you want to clear the separate Guest Mode data from this browser?',okText:'Clear Guest Data',cancelText:'Keep Guest Data',danger:true});if(clear){guestData=freshGuestData();localStorage.setItem(GUEST_KEY,JSON.stringify(guestData))}toast('Guest data moved into your account.')}}});
$('#loginForm').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.target),email=fd.get('email').trim().toLowerCase();if(!db.users[email]||db.users[email].password!==fd.get('password'))return toast('Email or password not found.');logIn(email);toast('Welcome back!');});
function logIn(email){currentUser=email;migrateUser(user());localStorage.setItem(SESSION_KEY,email);closeAuth();$('#landing').classList.remove('active');$('#publicNav').classList.add('hidden');$('#app').classList.remove('hidden');renderAll();showView('dashboard')}
function enterGuestMode(){guestData=loadGuestData();currentUser=GUEST_SESSION;migrateUser(user());localStorage.setItem(SESSION_KEY,GUEST_SESSION);closeAuth();$('#landing').classList.remove('active');$('#publicNav').classList.add('hidden');$('#app').classList.remove('hidden');renderAll();showView('dashboard');toast('Continuing as Guest Student.')}
async function logOut(){if(isGuestMode()){const exit=await confirmDialog({title:'Exit Guest Mode',message:'Do you want to exit guest mode?',okText:'Exit Guest Mode',cancelText:'Cancel'});if(!exit)return}else toast('You are logged out.');localStorage.removeItem(SESSION_KEY);currentUser=null;$('#app').classList.add('hidden');$('#landing').classList.add('active');$('#publicNav').classList.remove('hidden')}
function cloneData(value){return JSON.parse(JSON.stringify(value))}
function moveGuestDataToAccount(source,target){['courses','customCourses','folders','notes','files','flashcards','quizzes','plans','activity'].forEach(k=>{target[k]=cloneData(source[k]||[])});target.progress=cloneData(source.progress||freshGuestData().progress)}
$('#logoutBtn').addEventListener('click',logOut);
/* Navigation */
const viewNames={dashboard:['OVERVIEW','Dashboard'],notes:['STUDY','My Notes'],noteDetail:['STUDY','Note Editor'],coach:['STUDY','AI Study Coach'],flashcards:['STUDY','Flashcards'],quiz:['STUDY','Quiz Generator'],planner:['STUDY','Study Planner'],progress:['INSIGHTS','Progress Tracker'],instructions:['HELP','How it works'],settings:['ACCOUNT','Account Settings']};
function showView(view){$$('.app-view').forEach(v=>v.classList.remove('active'));$(`#${view}View`).classList.add('active');$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view&&b.closest('#appNav')));$('#breadcrumb').textContent=viewNames[view][0];$('#viewTitle').textContent=viewNames[view][1];$('.sidebar').classList.remove('open');if(view==='progress')renderProgress();if(view==='dashboard')renderDashboard();if(view==='settings')renderSettings();if(view==='noteDetail')renderNoteDetail();if(view==='planner')renderPlannerPlan();window.scrollTo(0,0)}
$$('[data-view]').forEach(btn=>btn.addEventListener('click',()=>showView(btn.dataset.view)));
document.addEventListener('click',e=>{const btn=e.target.closest('.open-settings-btn');if(btn)showView('settings')});
$('#menuBtn').addEventListener('click',()=>$('.sidebar').classList.toggle('open'));
$$('[data-premium]').forEach(b=>b.addEventListener('click',()=>$('#premiumModal').classList.add('open')));$$('[data-premium-close]').forEach(b=>b.addEventListener('click',()=>$('#premiumModal').classList.remove('open')));

function courseSettingsButton(){return '<button class="btn btn-secondary open-settings-btn" data-view="settings" type="button">Open Account Settings</button>'}
function courseEmptyMessage(){return '<div class="course-empty-message">No courses selected. Go to Account Settings to choose your courses. '+courseSettingsButton()+'</div>'}
function bindSettingsShortcuts(){$$('[data-view="settings"]').forEach(btn=>btn.onclick=()=>showView('settings'))}
function renderSettings(){const u=user();if(!u)return;const guest=isGuestMode();$('#settingsName').value=u.name||'';$('#settingsEmail').value=u.email||'';$('#settingsGrade').value=u.grade||'Grade 9';$('#settingsName').disabled=guest;$('#settingsEmail').disabled=guest;$('#settingsEmail').required=!guest;$('#settingsGrade').disabled=guest;$('#saveProfileBtn')?.classList.toggle('hidden',guest);$('#clearGuestDataBtn')?.classList.toggle('hidden',!guest);$('#profileHelp').textContent=guest?'Guest profile details are fixed. Course choices and custom courses still save on this browser.':'Your account details are saved in this browser.';$('#settingsCourses').innerHTML=appData.courses.length?courseButtons('settingsCourses',selectedCourses(),appData.courses):'<div class="empty-mini">Course list is loading. If it stays empty, fallback courses will be available.</div>';renderCustomCourseList();bindCustomCourseActions()}
function refreshAfterCourseChange(){updateSubjectSelects();renderDashboard();renderNotes();renderOrganization();renderProgress();renderSettings();bindSettingsShortcuts()}
function renderCustomCourseList(){const selected=selectedCourses(),courses=customCourses();$('#customCourseList').innerHTML=courses.length?courses.map(c=>`<div class="custom-course-row" data-custom-row="${escapeHTML(c)}"><div class="custom-course-view"><label class="course-chip custom-chip"><input type="checkbox" name="settingsCourses" value="${escapeHTML(c)}" ${selected.includes(c)?'checked':''}><span>${escapeHTML(c)}</span></label><div><button type="button" data-custom-rename="${escapeHTML(c)}">Rename</button><button type="button" data-custom-delete="${escapeHTML(c)}">Delete</button></div></div><div class="custom-course-edit hidden"><input data-custom-edit-input maxlength="30" value="${escapeHTML(c)}"><button type="button" data-custom-save="${escapeHTML(c)}">Save</button><button type="button" data-custom-cancel>Cancel</button></div></div>`).join(''):'<div class="empty-mini">No custom courses yet.</div>'}
function addCustomCourse(){const input=$('#customCourseName'),name=normalizeCourseName(input.value);if(!name)return toast('Enter a course name.');if(name.length>30)return toast('Custom course names must be 30 characters or less.');if(courseExists(name))return toast('That course already exists.');const u=user();u.customCourses=uniqueCourses([...(u.customCourses||[]),name]);u.courses=uniqueCourses([...(u.courses||[]),name]);input.value='';$('#customCourseForm').classList.add('hidden');saveDB();refreshAfterCourseChange();toast('Custom course added.')}
function renameCustomCourse(btn){const row=btn.closest('.custom-course-row');$('.custom-course-view',row).classList.add('hidden');$('.custom-course-edit',row).classList.remove('hidden');$('[data-custom-edit-input]',row).focus()}
function saveCustomCourseRename(btn,oldName){const row=btn.closest('.custom-course-row'),current=customCourses().find(c=>c.toLowerCase()===oldName.toLowerCase()),next=normalizeCourseName($('[data-custom-edit-input]',row).value);if(!current)return;if(!next)return toast('Enter a course name.');if(next===current)return renderSettings();if(next.length>30)return toast('Custom course names must be 30 characters or less.');if(courseExists(next,customCourses().filter(c=>c.toLowerCase()!==current.toLowerCase())))return toast('That course already exists.');const u=user(),same=x=>x.toLowerCase()===current.toLowerCase();u.customCourses=uniqueCourses(u.customCourses.map(c=>same(c)?next:c));u.courses=uniqueCourses(u.courses.map(c=>same(c)?next:c));u.notes.forEach(n=>{if(same(n.subject))n.subject=next});u.flashcards.forEach(c=>{if(same(c.subject))c.subject=next});u.quizzes.forEach(q=>{if(same(q.subject))q.subject=next});u.plans.forEach(p=>{if(same(p.subject))p.subject=next;p.courses=(p.courses||[]).map(c=>same(c)?next:c)});saveDB();refreshAfterCourseChange();toast('Custom course renamed.')}
function deleteCustomCourse(name){const current=customCourses().find(c=>c.toLowerCase()===name.toLowerCase());if(!current)return;const u=user(),same=x=>x.toLowerCase()===current.toLowerCase();u.customCourses=uniqueCourses(u.customCourses.filter(c=>!same(c)));u.courses=uniqueCourses(u.courses.filter(c=>!same(c)));saveDB();refreshAfterCourseChange();toast('Custom course deleted.')}
function bindCustomCourseActions(){$$('[data-custom-rename]').forEach(b=>b.onclick=()=>renameCustomCourse(b));$$('[data-custom-save]').forEach(b=>b.onclick=()=>saveCustomCourseRename(b,b.dataset.customSave));$$('[data-custom-cancel]').forEach(b=>b.onclick=()=>renderSettings());$$('[data-custom-delete]').forEach(b=>b.onclick=()=>deleteCustomCourse(b.dataset.customDelete));$$('[data-custom-edit-input]').forEach(i=>i.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();saveCustomCourseRename(i.closest('.custom-course-row').querySelector('[data-custom-save]'),i.closest('.custom-course-row').dataset.customRow)}})}
$('#profileForm').addEventListener('submit',e=>{e.preventDefault();if(isGuestMode())return toast('Guest profile details are fixed.');const u=user(),oldEmail=currentUser,newEmail=$('#settingsEmail').value.trim().toLowerCase();if(!newEmail)return toast('Add an email address.');if(newEmail!==oldEmail&&db.users[newEmail])return toast('Another account already uses that email.');u.name=$('#settingsName').value.trim()||u.name;u.email=newEmail;u.grade=$('#settingsGrade').value;if(newEmail!==oldEmail){db.users[newEmail]=u;delete db.users[oldEmail];currentUser=newEmail;localStorage.setItem(SESSION_KEY,newEmail)}saveDB();renderAll();showView('settings');toast('Profile updated.')});
$('#coursesForm').addEventListener('submit',e=>{e.preventDefault();user().courses=$$('input[name="settingsCourses"]:checked').map(x=>x.value);delete user().subjects;saveDB();refreshAfterCourseChange();toast('Courses saved. Dropdowns updated.')});
$('#clearGuestDataBtn')?.addEventListener('click',async()=>{if(!isGuestMode())return;const clear=await confirmDialog({title:'Clear Guest Data',message:'This will delete all guest notes, folders, quizzes, flashcards, plans, and progress.',okText:'Clear Guest Data',cancelText:'Cancel',danger:true});if(!clear)return;guestData=freshGuestData();localStorage.setItem(GUEST_KEY,JSON.stringify(guestData));renderAll();showView('settings');toast('Guest data cleared.')});
$('#showCustomCourseBtn').addEventListener('click',()=>{$('#customCourseForm').classList.toggle('hidden');$('#customCourseName').focus()});
$('#addCustomCourseBtn').addEventListener('click',addCustomCourse);
$('#customCourseName').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();addCustomCourse()}});

/* Folder organization. Every study item stores a folderId in localStorage. */
function folderById(id){return user().folders.find(f=>f.id===id)}
function uncategorized(){return folderById(SYSTEM_FOLDER_ID)}
function visibleFolders(){return user().folders.filter(f=>!f.protected)}
function normalizeFolderId(id){return folderById(id)&&!folderById(id).protected?id:SYSTEM_FOLDER_ID}
function folderOptions(){const options=visibleFolders().map(f=>`<option value="${f.id}">${escapeHTML(f.name)}</option>`).join('');return '<option value="">No folder</option>'+options}
function displayFolderName(id){const f=folderById(id);return f&&!f.protected?f.name:'No folder'}
function touchFolder(id){const f=folderById(id);if(f)f.updated=today()}
function openFolderModal(id=''){const f=folderById(id);if(f?.protected)return toast('That system folder cannot be renamed.');$('#folderEditId').value=id;$('#folderName').value=f?.name||'';$('#folderModalTitle').textContent=f?'Rename folder':'Create a folder';$('#folderModal').classList.add('open');$('#folderName').focus()}
function closeFolderModal(){$('#folderModal').classList.remove('open')}
function folderDescendants(id){const found=[];const walk=parent=>user().folders.filter(f=>f.parentId===parent).forEach(f=>{found.push(f.id);walk(f.id)});walk(id);return found}
function openDeleteFolder(id){const f=folderById(id);if(!f||f.protected)return toast('That system folder cannot be deleted.');$('#deleteFolderId').value=id;$('input[name="deleteMode"][value="folder"]').checked=true;$('#deleteFolderModal').classList.add('open')}
function closeDeleteFolder(){$('#deleteFolderModal').classList.remove('open')}
