function keywords(text){const counts={};(text.toLowerCase().match(/[a-z]{4,}/g)||[]).forEach(w=>{if(!stopWords.has(w))counts[w]=(counts[w]||0)+1});return Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,7).map(x=>x[0])}
