function generateCardsFromNote(note){const folderId=normalizeFolderId(note.folderId),sentences=statementsFromText(note.text),keys=keywords(note.text);currentCards=sentences.slice(0,5).map((s,i)=>{const key=keys.find(k=>s.toLowerCase().includes(k))||keys[i]||'this concept';return {id:'c'+Date.now()+i,subject:note.subject,folderId,question:`What should you remember about ${key}?`,answer:s,topic:key}});while(currentCards.length<5)currentCards.push({id:'c'+Date.now()+currentCards.length,subject:note.subject,folderId,question:`What is a key idea from ${note.title}?`,answer:summarize(note.text),topic:keys[currentCards.length]||note.subject});user().flashcards.push(...currentCards);touchFolder(folderId);cardIndex=0;saveDB();activeNoteId=null;showView('flashcards');$('#flashEmpty').classList.add('hidden');$('#flashStudy').classList.remove('hidden');showCard();recordActivity('card',`Generated 5 flashcards from ${note.title}`)}
function buildQuizFromNote(note){const sentences=statementsFromText(note.text),keys=keywords(note.text);return Array.from({length:5},(_,i)=>{const sentence=sentences[i%Math.max(sentences.length,1)]||note.text;const answer=keys.find(k=>sentence.toLowerCase().includes(k))||keys[i%Math.max(keys.length,1)]||note.subject;const wrong=keys.filter(k=>k!==answer).slice(0,3);while(wrong.length<3)wrong.push(['concept','process','evidence'][wrong.length]);const options=[answer,...wrong].sort(()=>Math.random()-.5);return {question:`Which term best connects to this idea: "${sentence.slice(0,105)}${sentence.length>105?'...':''}"`,answer,options,explanation:`The note connects this idea with ${answer}: ${sentence}`}})}
