function mockCoachReply(q){q=q.toLowerCase();if(q.includes('biology'))return 'Use active recall: sketch the process or structure from memory, label it, then compare it with your notes. Follow with five flashcards and a short quiz. Spend extra time explaining â€œwhy,â€ not only naming parts.';if(q.includes('before')||q.includes('test'))return 'Start with a quick brain dump of everything you remember. Check it against your notes, mark the gaps, then review those weak areas with flashcards. Finish with a timed quiz and explain every missed answer aloud.';if(q.includes('procrast'))return 'Make the first step tiny: set a 10-minute timer and open one note. Put your phone out of reach, choose one specific outcome, and stop after 10 minutes if you want. Starting is the real assignment.';if(q.includes('math'))return 'For math, spend less time rereading and more time solving. Work one example with notes, one without notes, then one mixed problem. Keep an error log that names exactly where each mistake happened.';return 'Try a three-part session: 10 minutes recalling what you know, 20 minutes practicing the hardest idea, and 5 minutes writing what to review next. Active recall will give you more useful feedback than rereading.'}
function sendCoach(q){const box=$('#chatMessages');box.insertAdjacentHTML('beforeend',`<div class="message user"><div><b>You</b><p>${escapeHTML(q)}</p></div></div>`);setTimeout(()=>{box.insertAdjacentHTML('beforeend',`<div class="message ai"><span class="bot-avatar">S</span><div><b>StudySpark Coach</b><p>${escapeHTML(mockCoachReply(q))}</p></div></div>`);box.scrollTop=box.scrollHeight},350);box.scrollTop=box.scrollHeight}
