function updateSubjectSelects(){if(!user())return;const courses=selectedCourses(),options=courseOptionsHTML(courses),folders=folderOptions(),empty=!courses.length;$$('.course-empty-message').forEach(x=>x.remove());$('#noteSubject').innerHTML=options;$('#flashSubject').innerHTML=options;$('#quizSubject').innerHTML=options;['#fileSubject','#uploadSubject'].forEach(id=>{if($(id))$(id).innerHTML=options});$('#noteFolder').innerHTML=folders;$('#flashFolder').innerHTML=folders;$('#quizFolder').innerHTML=folders;$('#planFolder').innerHTML=folders;$('#planCourses').innerHTML=courses.length?courseButtons('planCourses',[],courses):courseEmptyMessage();if(empty){$('#noteSubject').closest('.form-row').insertAdjacentHTML('afterend',courseEmptyMessage());$('#flashSubject').parentElement.insertAdjacentHTML('beforeend',courseEmptyMessage());$('#quizSubject').parentElement.insertAdjacentHTML('beforeend',courseEmptyMessage())}bindSettingsShortcuts()}
function subjectNotes(subject){return user().notes.filter(n=>n.subject===subject)}
function statementsFor(subject){const text=subjectNotes(subject).map(n=>n.text).join(' ');return (text.match(/[^.!?]+[.!?]+|[^.!?]+$/g)||[]).map(s=>s.trim()).filter(s=>s.split(' ').length>4)}

/* Flashcards */
function generateCards(){const subject=$('#flashSubject').value,folderId=normalizeFolderId($('#flashFolder').value),notes=subjectNotes(subject);if(!notes.length)return toast('Save notes for this course first.');const sentences=statementsFor(subject),keys=keywords(notes.map(n=>n.text).join(' '));currentCards=sentences.slice(0,5).map((s,i)=>{const key=keys.find(k=>s.toLowerCase().includes(k))||keys[i]||'this concept';return {id:'c'+Date.now()+i,subject,folderId,question:`What should you remember about ${key}?`,answer:s,topic:key}});while(currentCards.length<5)currentCards.push({id:'c'+Date.now()+currentCards.length,subject,folderId,question:`What is a key idea from ${notes[0].title}?`,answer:summarize(notes[0].text),topic:keys[currentCards.length]||subject});user().flashcards.push(...currentCards);touchFolder(folderId);cardIndex=0;saveDB();$('#flashEmpty').classList.add('hidden');$('#flashStudy').classList.remove('hidden');showCard();recordActivity('card',`Generated 5 ${subject} flashcards`)}
function showCard(){if(cardIndex>=currentCards.length){$('#flashStudy').innerHTML='<div class="empty-state card"><span class="empty-icon">âœ“</span><h2>Deck complete</h2><p>Your card progress has been saved. Review weak topics in Progress.</p><button class="btn btn-primary" onclick="location.reload()">Study another deck</button></div>';return}const c=currentCards[cardIndex];$('#flashcard').classList.remove('flipped');$('#flashQuestion').textContent=c.question;$('#flashAnswer').textContent=c.answer;$('#cardCounter').textContent=`Card ${cardIndex+1} of ${currentCards.length}`;$('#cardProgress').style.width=(cardIndex/currentCards.length*100)+'%';$('#knownCount').textContent=user().progress.cardsKnown}
function markCard(known){const c=currentCards[cardIndex];user().progress.cardsCompleted++;if(known)user().progress.cardsKnown++;else if(!user().progress.weakTopics.includes(c.topic))user().progress.weakTopics.push(c.topic);user().progress.minutes+=2;saveDB();cardIndex++;showCard()}
$('#generateCardsBtn').addEventListener('click',generateCards);$('#flashcard').addEventListener('click',()=>$('#flashcard').classList.toggle('flipped'));$('#flashcard').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' ')$('#flashcard').classList.toggle('flipped')});$('#knowCardBtn').addEventListener('click',()=>markCard(true));$('#reviewCardBtn').addEventListener('click',()=>markCard(false));

/* Quiz generation â€” mock logic. Replace buildQuiz with a real AI API response later. */
function buildQuiz(subject){const notes=subjectNotes(subject),sentences=statementsFor(subject),keys=keywords(notes.map(n=>n.text).join(' '));return Array.from({length:5},(_,i)=>{const sentence=sentences[i%sentences.length]||notes[0].text;const answer=keys.find(k=>sentence.toLowerCase().includes(k))||keys[i%keys.length]||subject;const wrong=keys.filter(k=>k!==answer).slice(0,3);while(wrong.length<3)wrong.push(['concept','process','evidence'][wrong.length]);const options=[answer,...wrong].sort(()=>Math.random()-.5);return {question:`Which term best connects to this idea: â€œ${sentence.slice(0,105)}${sentence.length>105?'â€¦':''}â€`,answer,options,explanation:`The notes connect this idea with ${answer}: ${sentence}`}})}
function generateQuiz(){const subject=$('#quizSubject').value;if(!subjectNotes(subject).length)return toast('Save notes for this subject first.');const quiz=buildQuiz(subject);$('#quizEmpty').classList.add('hidden');$('#quizResult').classList.add('hidden');const form=$('#quizForm');form.dataset.subject=subject;form._quiz=quiz;form.innerHTML=quiz.map((q,i)=>`<article class="card quiz-question"><span>QUESTION ${i+1} OF 5</span><h3>${escapeHTML(q.question)}</h3><div class="options">${q.options.map(o=>`<label class="option"><input type="radio" name="q${i}" value="${escapeHTML(o)}"> ${escapeHTML(o[0].toUpperCase()+o.slice(1))}</label>`).join('')}</div><div class="explanation hidden"></div></article>`).join('')+'<button class="btn btn-primary" type="submit">Submit answers</button>';form.classList.remove('hidden')}
$('#generateQuizBtn').addEventListener('click',generateQuiz);$('#quizForm').addEventListener('submit',e=>{e.preventDefault();const quiz=e.target._quiz;let correct=0;quiz.forEach((q,i)=>{const chosen=$(`input[name="q${i}"]:checked`,e.target)?.value;const card=$$('.quiz-question',e.target)[i];$$('.option',card).forEach(l=>{const val=$('input',l).value;l.classList.toggle('correct',val===q.answer);l.classList.toggle('wrong',val===chosen&&chosen!==q.answer)});const ex=$('.explanation',card);ex.textContent=q.explanation;ex.classList.remove('hidden');if(chosen===q.answer)correct++});const score=correct*20;user().quizzes.push({subject:e.target.dataset.subject,score,date:new Date().toLocaleDateString(undefined,{month:'short',day:'numeric'})});user().progress.minutes+=10;recordActivity('quiz',`Scored ${score}% in ${e.target.dataset.subject}`);$('#quizResult').innerHTML=`<span class="pill blue-pill">QUIZ COMPLETE</span><h2>You scored <b>${score}%</b></h2><p>${correct} of 5 correct. Review the explanations above, then try again when you're ready.</p>`;$('#quizResult').classList.remove('hidden');e.target.querySelector('button[type="submit"]').disabled=true;$('#quizResult').scrollIntoView({behavior:'smooth'})});
$('#quizForm').addEventListener('submit',()=>{setTimeout(()=>{const q=user().quizzes[user().quizzes.length-1];if(q){q.folderId=normalizeFolderId($('#quizFolder').value);touchFolder(q.folderId);saveDB();renderOrganization()}},0)});

/* Planner */
function setMinDate(){const d=new Date();$('#testDate').min=d.toISOString().slice(0,10);if(!$('#testDate').value){const next=new Date(Date.now()+6*86400000);$('#testDate').value=next.toISOString().slice(0,10)}}
function localDate(value){const d=value?new Date(value+'T12:00:00'):new Date();return new Date(d.getFullYear(),d.getMonth(),d.getDate(),12)}
function addDays(date,days){const d=new Date(date);d.setDate(d.getDate()+days);return d}
function formatPlanDate(date){return date.toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}
function daysUntilTest(testDate){const start=localDate(today()),test=localDate(testDate);return Math.ceil((test-start)/86400000)}
function splitTopics(value=''){return uniqueCourses(value.split(/[,;\n]+/).flatMap(t=>expandTopicParts(t.trim())).filter(Boolean)).slice(0,36)}
function expandTopicParts(topic){if(!topic)return[];const lower=topic.toLowerCase(),extras=[];if(lower.includes('polynomial'))extras.push('polynomial vocabulary','degree and leading coefficient','polynomial rules');if(lower.includes('factor'))extras.push('greatest common factor','factoring by grouping','difference of squares');if(lower.includes('zero')||lower.includes('root'))extras.push('zeros and x-intercepts','multiplicity','solving from factored form');if(lower.includes('graph'))extras.push('graph shape','x-intercepts and y-intercepts','turning points');if(lower.includes('transform'))extras.push('vertical shifts','stretches and compressions','reflections');if(lower.includes('word'))extras.push('word problem setup','choosing variables','checking reasonableness');return uniqueCourses([topic,...extras])}
function plannerTemplateFor(course){const templates=appData.plannerTemplates||FALLBACK_PLANNER_TEMPLATES,key=Object.keys(templates).find(k=>k!=='fallback'&&(templates[k].keywords||[]).some(w=>course.toLowerCase().includes(w)));return templates[key]||templates.fallback}
function noteKeywordsForPlan(course,folderId){const same=x=>x.subject&&x.subject.toLowerCase()===course.toLowerCase(),folder=normalizeFolderId(folderId);const notes=user().notes.filter(n=>same(n)&&(!folderId||n.folderId===folder));return uniqueCourses(keywords(notes.map(n=>`${n.title} ${n.text}`).join(' ')).slice(0,10))}
function reviewDayType(index,total){const day=index+1;if(total<=1)return 'emergency';if(total<=3&&day===total)return 'final';if(total<=7&&day===total)return 'final';if(total<=14&&(day===Math.ceil(total/2)||day===total))return day===total?'final':'mid';if(total>14&&(day%7===0||day===total))return day===total?'final':'weekly';return ''}
function pickFrom(list,index,fallback='Review {topic}.'){return (list&&list.length?list:[fallback])[index%(list&&list.length?list.length:1)]}
function fillTemplate(text,topic,minutes){return (text||'Review {topic}.').replaceAll('{topic}',topic).replaceAll('{practiceCount}',String(Math.max(5,Math.round(minutes/5))))}
function countValue(list,value,key){return list.filter(item=>item[key]===value).length}
const PLAN_VERBS=['Identify','Solve','Explain','Complete','Review','Compare','Practice','Analyze','Create','Write','Build','List','Read','Update','Redo','Rank','Skim','Make','Study','Correct','Choose','Sort','Define','Label','Draft','Revise','Connect','Answer','Apply','Find','Factor','Verify','Plot','Check','Determine','Match','Describe','Work','Rewrite','Group'];
function cleanPlanText(text=''){return String(text).replace(/\s+/g,' ').replace(/\s+([,.!?;:])/g,'$1').replace(/[“”]/g,'"').replace(/[‘’]/g,"'").replace(/\bteh\b/gi,'the').replace(/\badn\b/gi,'and').replace(/\byour your\b/gi,'your').trim()}
function sentenceCase(text){return text?text.charAt(0).toUpperCase()+text.slice(1):text}
function completeSentence(text,fallback){let value=cleanPlanText(text||fallback);if(!value)return fallback;if(!/[.!?]$/.test(value))value+='.';return value}
function startsWithPlanVerb(text){return PLAN_VERBS.some(verb=>new RegExp(`^${verb}\\b`,'i').test(text))}
function actionSentence(text,fallback='Review the study task.'){let value=completeSentence(text,fallback);if(!startsWithPlanVerb(value))value=`Review ${value.charAt(0).toLowerCase()+value.slice(1)}`;return sentenceCase(completeSentence(value,fallback))}
function repairBrokenPlannerFragments(text=''){return cleanPlanText(text).replace(/\bappl\.?\b|\bapplic\.?\b/gi,'applications').replace(/\bques\.?\b/gi,'questions').replace(/\bfunc\.?\b/gi,'function').replace(/\bpoly\.?\b/gi,'polynomial').replace(/\bdef\.?\b/gi,'definition').replace(/\bcalc\.?\b/gi,'calculation').replace(/\b(\w+)\s+\1\b/gi,'$1').replace(/\b(practice|questions|function|polynomial|application|applications)\s+\1\b/gi,'$1')}
function shortTopicName(topic=''){const value=repairBrokenPlannerFragments(topic),lower=value.toLowerCase();if(lower.includes('rational')&&lower.includes('word'))return 'rational function word problems';if(lower.includes('rational')&&lower.includes('applic'))return 'rational function applications';if(lower.includes('rational'))return 'rational functions';if(lower.includes('factoring by grouping'))return 'factoring by grouping';if(lower.includes('greatest common factor'))return 'GCF factoring';if(lower.includes('difference of squares'))return 'difference of squares';if(lower.includes('zeros')||lower.includes('x-intercepts'))return 'zeros and intercepts';if(lower.includes('transformation'))return 'transformations';if(lower.includes('word problem'))return 'word problems';return value.length>54?'the main topic':value}
function hasBrokenPlannerText(text){const value=repairBrokenPlannerFragments(text),lower=value.toLowerCase();return !value||/\b(appl|applic|ques|func|poly|def|calc)\.?($|\s)/i.test(value)||/\b(or|and|from|with|for|to|apply|review|choose)\.$/i.test(value)||/\bfrom\s+[a-z]+\.?$/i.test(value)||/(\b\w+\b)(\s+\1\b)+/i.test(lower)||value.length>170}
const PLAN_PURPOSES=['Learn key concepts','Work through examples','Build core skills','Solve application questions','Correct mistakes','Use flashcards and recall','Complete mixed review','Run a final test simulation','Create a final summary','Teach back the topic'];
function planPurpose(index,total,reviewType){if(reviewType==='emergency')return 'Emergency same-day review';if(reviewType==='final')return total<=3?'Final mixed review':'Run a final test simulation';if(reviewType==='mid')return 'Complete mixed review';if(reviewType==='weekly')return 'Weekly mixed review';const day=index+1;if(total===1)return 'Emergency same-day review';if(day===total)return 'Run a final test simulation';const ratio=day/total;if(ratio<.22)return PLAN_PURPOSES[index%2];if(ratio<.48)return ['Build core skills','Solve application questions','Use flashcards and recall'][index%3];if(ratio<.76)return ['Correct mistakes','Complete mixed review','Solve application questions'][index%3];return ['Complete mixed review','Create a final summary','Teach back the topic'][index%3]}
function purposeInstructions(purpose,topic,minutes){const count=Math.max(6,Math.round((minutes||45)/5)),challenge=Math.max(2,Math.round(count/4));const sets={whatToStudy:{'Learn key concepts':`Study the definitions, rules, and teacher-highlighted examples for ${topic}. Build a one-page summary sheet that explains the main ideas in your own words before doing any practice.`,'Work through examples':`Choose two or three worked examples about ${topic}. Read each line slowly, label why each step works, and copy one example with short notes in the margin.`,'Build core skills':`Focus on the exact skills needed for ${topic}. List the steps, formulas, or decision rules, then mark the parts that still feel slow or confusing.`,'Solve application questions':`Look for ways ${topic} appears in word problems, graphs, diagrams, or real situations. Write down the clues that tell you which method to use.`,'Correct mistakes':`Open your notes, quizzes, and practice work for ${topic}. Find the mistakes, group them by type, and choose the errors that would cost the most marks on a test.`,'Use flashcards and recall':`Turn the key vocabulary, formulas, rules, and examples for ${topic} into quick recall prompts. Focus on facts you should know without checking your notes.`,'Complete mixed review':`Review ${topic} together with related topics from this unit. Look for similarities, differences, and question types that could be mixed on the test.`,'Run a final test simulation':`Prepare for ${topic} like a test session. Gather only the tools your teacher allows, clear distractions, and decide how much time you will spend on each question type.`,'Create a final summary':`Condense ${topic} into a final study sheet. Include key rules, common question types, one model example, and the mistakes you need to avoid.`,'Teach back the topic':`Review ${topic} by preparing to teach it. Decide what a classmate would need to know first, then organize the explanation from easiest to hardest.`,'Emergency same-day review':`Review the highest-priority ideas for ${topic}. Focus on the rules, examples, and mistakes that are most likely to appear on the test today.`,'Final mixed review':`Revisit ${topic} and the connected unit topics. Focus on test-style questions, common traps, and the ideas your teacher emphasized most.`,'Weekly mixed review':`Revisit ${topic} with the other topics studied this week. Mark what is secure, what needs more practice, and what should appear in next week’s review.`},stepByStepTask:{'Learn key concepts':`1. Read your notes on ${topic}.\n2. Highlight the main rules and vocabulary.\n3. Rewrite each rule in student-friendly language.\n4. Add one example beside each rule.\n5. Circle anything that still needs a question for your teacher.`,'Work through examples':`1. Select two worked examples for ${topic}.\n2. Cover the solution and predict the first step.\n3. Reveal one line at a time and explain the reason for it.\n4. Redo one example without looking.\n5. Compare your redo with the original solution.`,'Build core skills':`1. List the main steps for ${topic}.\n2. Complete three easy questions slowly and accurately.\n3. Complete five medium questions without notes.\n4. Check each answer and mark slow steps.\n5. Repeat the weakest step until it feels smoother.`,'Solve application questions':`1. Read each application problem twice.\n2. Underline the given information and the question being asked.\n3. Choose the method that fits ${topic}.\n4. Solve and label each step.\n5. Check whether the answer makes sense in the situation.`,'Correct mistakes':`1. Choose three missed questions about ${topic}.\n2. Identify the exact line where each mistake started.\n3. Write why the correct method works.\n4. Redo each question without notes.\n5. Add one warning sentence for future practice.`,'Use flashcards and recall':`1. Make quick prompts for vocabulary, formulas, and examples from ${topic}.\n2. Answer each prompt without notes.\n3. Sort prompts into easy and hard piles.\n4. Restudy the hard pile.\n5. Test yourself again after a short break.`,'Complete mixed review':`1. Mix ${topic} with two related topics.\n2. Sort questions by type before solving.\n3. Complete one question from each type.\n4. Explain why each method fits.\n5. Redo the question type that took the longest.`,'Run a final test simulation':`1. Set a timer for a short test block.\n2. Complete questions about ${topic} without notes.\n3. Skip and return to questions that get stuck.\n4. Check answers only after the timer ends.\n5. Record the mistakes to review before the test.`,'Create a final summary':`1. Write the most important rules for ${topic}.\n2. Add one solved example.\n3. Add common mistakes and how to avoid them.\n4. Add a short practice question.\n5. Use the page to teach the topic from memory.`,'Teach back the topic':`1. Explain ${topic} aloud from the beginning.\n2. Use one example while you explain.\n3. Pause when the explanation becomes unclear.\n4. Check notes only for the unclear part.\n5. Explain it again more clearly.`},practiceQuestions:{default:`Complete ${count} practice questions about ${topic}.\n- Use 5 easier ${topic} questions to warm up.\n- Use 5 medium ${topic} questions to build accuracy.\n- Finish with ${challenge} challenge or test-style ${topic} questions.`},mistakeCheck:{default:`Review every incorrect answer from today's ${topic} work. Write why the ${topic} mistake happened, solve it again correctly, and note the step to remember next time.`},miniReview:{default:`End by writing 5 to 10 bullet points about ${topic}, or explain the day’s focus aloud as if teaching it to a classmate.`}};return {whatToStudy:sets.whatToStudy[purpose]||sets.whatToStudy['Learn key concepts'],stepByStepTask:sets.stepByStepTask[purpose]||sets.stepByStepTask['Build core skills'],practiceQuestions:sets.practiceQuestions.default,mistakeCheck:sets.mistakeCheck.default,miniReview:sets.miniReview.default}}
function plannerTaskFallback(key,day){const topic=shortTopicName(day.mainTopic||'the test topic'),purpose=day.purpose||day.taskType||'Build core skills';return purposeInstructions(purpose,topic,day.estimatedMinutes||45)[key]||`Review the key ideas in ${topic}.`}
function validatedPlanSentence(text,fallback){if(!text)return fallback;let value=repairBrokenPlannerFragments(text);if(hasBrokenPlannerText(value))return fallback;return actionSentence(value,fallback)}
function sentenceParts(text=''){return repairBrokenPlannerFragments(text).split(/(?<=[.!?])\s+|\n+/).map(s=>cleanPlanText(s)).filter(Boolean)}
function repeatedSentence(text,seen){return sentenceParts(text).some(s=>seen.has(s.toLowerCase()))}
function rememberSentences(text,seen){sentenceParts(text).forEach(s=>seen.add(s.toLowerCase()))}
function nextPurpose(current,index,total,used){for(let offset=0;offset<PLAN_PURPOSES.length;offset++){const candidate=planPurpose(index+offset,total,'');if(!used.has(candidate.toLowerCase()))return candidate}return `${current} focus`}
function qualityCheckStudyPlan(plan){if(!plan)return plan;migratePlanDays(plan);const seenTitles=new Set(),seenPurposes=new Set(),seenSentences=new Set();plan.days.forEach((day,index)=>{day.mainTopic=repairBrokenPlannerFragments(day.mainTopic||'Study focus');if(seenTitles.has(day.mainTopic.toLowerCase()))day.mainTopic=`${day.mainTopic} application`;seenTitles.add(day.mainTopic.toLowerCase());day.purpose=day.purpose||day.taskType||planPurpose(index,plan.days.length,'');if(index&&plan.days[index-1].purpose===day.purpose)day.purpose=nextPurpose(day.purpose,index,plan.days.length,seenPurposes);if(seenPurposes.has(day.purpose.toLowerCase()))day.purpose=nextPurpose(day.purpose,index+1,plan.days.length,seenPurposes);seenPurposes.add(day.purpose.toLowerCase());day.taskType=repairBrokenPlannerFragments(day.purpose);day.practiceType=repairBrokenPlannerFragments(day.practiceType||'focused practice');day.subtopics=(day.subtopics||[]).map(repairBrokenPlannerFragments).filter(Boolean);['whatToStudy','stepByStepTask','practiceQuestions','mistakeCheck','miniReview'].forEach(key=>{const fallback=plannerTaskFallback(key,day),raw=day[key]||'',current=repairBrokenPlannerFragments(raw);day[key]=(raw.includes('\n')&&!hasBrokenPlannerText(current)&&!repeatedSentence(raw,seenSentences))?raw:(!current||current.length<95||hasBrokenPlannerText(current)||repeatedSentence(current,seenSentences))?fallback:validatedPlanSentence(current,fallback);rememberSentences(day[key],seenSentences)});delete day.checklist});return plan}
function nextUniqueTopic(pool,index,usedMainTopics,reviewType){if(reviewType==='final')return 'Final mixed review';if(reviewType==='mid')return 'Midpoint mixed review';if(reviewType==='weekly')return 'Weekly cumulative review';if(reviewType==='emergency')return 'Emergency high-priority review';if(!pool.length)return 'Core test material';for(let offset=0;offset<pool.length;offset++){const candidate=pool[(index+offset)%pool.length];if(!usedMainTopics.has(candidate.toLowerCase()))return candidate}return `${pool[index%pool.length]} application review`}
function topicBundle(topics,noteKeys,index,reviewType,usedMainTopics){const pool=uniqueCourses([...topics,...noteKeys]);const main=nextUniqueTopic(pool,index,usedMainTopics,reviewType);if(!reviewType)usedMainTopics.add(main.toLowerCase());const subs=reviewType?pool.slice(0,6):uniqueCourses([main,pool[(index+1)%pool.length],pool[(index+2)%pool.length]].filter(Boolean));return {main,subs:subs.length?subs:['highest-value notes','teacher examples','missed questions']}}
function usageCount(map,value){return map.get(value)||0}
function markUsed(map,value){map.set(value,usageCount(map,value)+1)}
function migratePlanDays(plan){const days=plan.days||plan.plan||[];days.forEach(day=>{delete day.checklist;day.completed=!!day.completed});plan.days=days;delete plan.plan;return plan}
function taskDetail(template,index,topic,minutes,purpose,usedTaskTypes=new Map(),usedPracticeTypes=new Map()){let taskType=purpose||pickFrom(template.taskTypes,index,'concept review'),practiceType=pickFrom(template.practiceTypes,index,'focused questions');for(let step=1;usageCount(usedPracticeTypes,practiceType)>=2&&step<6;step++)practiceType=pickFrom(template.practiceTypes,index+step,practiceType);return {purpose:taskType,taskType,practiceType,...purposeInstructions(taskType,topic,minutes)}}
function reviewDetail(reviewType,topic,subs,minutes,template){const names={emergency:'Emergency same-day review',mid:'Midpoint mixed review',weekly:'Weekly cumulative review',final:'Final mixed review'},focus=subs.slice(0,6).join(', ')||topic,count=Math.max(6,Math.round(minutes/6));return {taskType:`${reviewType} review`,practiceType:pickFrom(template.practiceTypes||[],subs.length,'mixed practice'),whatToStudy:reviewType==='emergency'?`Review the highest-priority topics: ${focus}. Build a one-page final summary that includes formulas, vocabulary, examples, and the mistakes you most need to avoid.`:`Revisit notes, examples, and teacher-highlighted ideas across ${focus}. Mark the ideas that feel weak, then choose the three most important ones for today's review.`,stepByStepTask:reviewType==='emergency'?`1. Rank the topics by test importance.\n2. Review the three topics that are most likely to appear.\n3. Complete one example from each topic.\n4. Write what you still forget.\n5. Spend the final minutes reviewing those weak points.`:`1. Create a mixed review sheet for ${focus}.\n2. Group the topics by question type.\n3. Complete one worked example from each group.\n4. Redo any example that feels unclear.\n5. Write a short final summary of what connects the topics.`,practiceQuestions:`Complete ${count} mixed practice questions across ${focus}.\n- Use easier questions first to warm up.\n- Use medium questions to check test readiness.\n- Use challenge questions for the topics that still feel weak.`,mistakeCheck:'Update your mistake log, redo missed questions, and write the correct reasoning beside each one.',miniReview:reviewType==='final'?'Do a final closed-notes recall. List formulas, vocabulary, examples, and the three most common mistakes to avoid.':'Make quick recall prompts for weak topics and answer them without notes.',mainTopic:names[reviewType]||topic}}
function ensurePlanQuality(days,template){return days.map((day,index)=>{if(index&&day.mainTopic===days[index-1].mainTopic)day.mainTopic=`${day.mainTopic} application`;if(countValue(days.slice(0,index),day.taskType,'taskType')>=2)day.taskType=pickFrom(template.taskTypes,index+2,day.taskType);if(countValue(days.slice(0,index),day.practiceType,'practiceType')>=2)day.practiceType=pickFrom(template.practiceTypes,index+2,day.practiceType);delete day.checklist;if(!day.practiceQuestions)day.practiceQuestions=plannerTaskFallback('practiceQuestions',day);if(!day.mistakeCheck)day.mistakeCheck=plannerTaskFallback('mistakeCheck',day);if(!day.miniReview)day.miniReview=plannerTaskFallback('miniReview',day);return day})}
function buildPlanDay({course,minutes,index,total,template,bundle,reviewType,usedTaskTypes,usedPracticeTypes}){const date=formatPlanDate(addDays(localDate(today()),index)),purpose=planPurpose(index,total,reviewType);let detail=reviewType?reviewDetail(reviewType,bundle.main,bundle.subs,minutes,template):taskDetail(template,index,bundle.main,minutes,purpose,usedTaskTypes,usedPracticeTypes);detail.purpose=detail.purpose||purpose;markUsed(usedTaskTypes,detail.taskType);markUsed(usedPracticeTypes,detail.practiceType);return {dayNumber:index+1,date,mainTopic:detail.mainTopic||bundle.main,subtopics:bundle.subs,purpose:detail.purpose,taskType:detail.taskType,practiceType:detail.practiceType,whatToStudy:detail.whatToStudy,stepByStepTask:detail.stepByStepTask,practiceQuestions:detail.practiceQuestions,mistakeCheck:detail.mistakeCheck,miniReview:detail.miniReview,estimatedMinutes:minutes,completed:false}}
function buildStudyPlan({course,folderId,testDate,minutesPerDay,topics}){const diff=daysUntilTest(testDate),total=Math.max(1,diff),template=plannerTemplateFor(course),noteKeys=noteKeywordsForPlan(course,folderId),combined=uniqueCourses([...topics,...noteKeys]),usedMainTopics=new Set(),usedTaskTypes=new Map(),usedPracticeTypes=new Map(),days=[];for(let index=0;index<total;index++){const reviewType=reviewDayType(index,total),bundle=topicBundle(combined,noteKeys,index,reviewType,usedMainTopics);days.push(buildPlanDay({course,minutes:minutesPerDay,index,total,template,bundle,reviewType,usedTaskTypes,usedPracticeTypes}))}return qualityCheckStudyPlan({id:'p'+Date.now(),course,folderId,subject:course,courses:[course],testDate,minutesPerDay,topics:combined.map(cleanPlanText),createdAt:new Date().toISOString(),days:ensurePlanQuality(days,template)})}
function plannerProgress(plan){migratePlanDays(plan);const total=plan?.days?.length||0,done=plan?.days?.filter(d=>d.completed).length||0;return {total,done,percent:total?Math.round(done/total*100):0}}
function updatePlanCompletion(plan,day,wasComplete){if(day.completed&&!wasComplete){user().progress.minutes+=(day.estimatedMinutes||0);touchStudy();recordActivity('note',`Completed day ${day.dayNumber} of ${plan.course||plan.subject} plan`)}else saveDB();renderPlannerPlan(plan);renderDashboard();renderProgress();renderOrganization()}
function renderPlannerPlan(plan=user().plans[0]){if(!plan){$('#scheduleTitle').textContent='A clear plan, one day at a time';$('#scheduleList').innerHTML='<div class="schedule-placeholder"><span>P</span><p>Your daily plan will appear here.</p></div>';return}qualityCheckStudyPlan(plan);const p=plannerProgress(plan),days=plan.days||[];saveDB();$('#scheduleTitle').textContent=`${plan.course||plan.subject} - ${days.length} day plan`;$('#scheduleList').innerHTML=`<div class="planner-progress"><div><b>${p.done} of ${p.total} days complete</b><span>${p.percent}%</span></div><div class="progress-line"><i style="width:${p.percent}%"></i></div></div>`+days.map(day=>`<article class="plan-day-card ${day.completed?'complete':''}"><div class="plan-day-head"><span class="schedule-day">DAY ${day.dayNumber}</span><div><b>${escapeHTML(day.mainTopic)}</b><small>${escapeHTML(day.date)} - ${day.estimatedMinutes} min</small></div><button class="btn ${day.completed?'btn-secondary':'btn-primary'}" data-plan-day="${plan.id}:${day.dayNumber}" type="button">${day.completed?'Day Complete':'&#10003; Mark Day Complete'}</button></div><div class="plan-subtopics">${(day.subtopics||[]).map(s=>`<span>${escapeHTML(s)}</span>`).join('')}</div><div class="plan-detail-stack"><section><span>Main Focus</span><p>${escapeHTML(day.taskType||day.mainTopic)}</p></section><section><span>What to Study</span><p>${escapeHTML(day.whatToStudy||day.studyTask||plannerTaskFallback('whatToStudy',day))}</p></section><section><span>Step-by-Step Tasks</span><p>${escapeHTML(day.stepByStepTask||plannerTaskFallback('stepByStepTask',day))}</p></section><section><span>Practice Questions</span><p>${escapeHTML(day.practiceQuestions||day.practiceTask||plannerTaskFallback('practiceQuestions',day))}</p></section><section><span>Estimated Study Time</span><p>${day.estimatedMinutes} minutes of focused study. Use the first part for review, the middle for practice, and the final minutes for correcting mistakes.</p></section><section><span>Mistake Check</span><p>${escapeHTML(day.mistakeCheck||plannerTaskFallback('mistakeCheck',day))}</p></section><section><span>Mini Review</span><p>${escapeHTML(day.miniReview||day.reviewTask||plannerTaskFallback('miniReview',day))}</p></section></div></article>`).join('');$$('[data-plan-day]').forEach(btn=>btn.onclick=()=>completePlanDay(btn.dataset.planDay))}
function completePlanDay(value){const [planId,dayNumber]=value.split(':'),plan=user().plans.find(p=>p.id===planId),day=plan?.days?.find(d=>String(d.dayNumber)===dayNumber);if(!day)return;const wasComplete=!!day.completed;day.completed=true;updatePlanCompletion(plan,day,wasComplete);toast('Study day completed.')}
$('#plannerForm').addEventListener('submit',e=>{e.preventDefault();const courses=$$('input[name="planCourses"]:checked').map(x=>x.value);if(!courses.length)return toast('Choose at least one course.');const course=courses[0],folderId=normalizeFolderId($('#planFolder').value),testDate=$('#testDate').value,topics=splitTopics($('#planTopics').value),minutesPerDay=Number($('#planMinutes').value);if(!topics.length)return toast('Add unit or test topics.');const plan=buildStudyPlan({course,folderId,testDate,minutesPerDay,topics});user().plans.unshift(plan);touchFolder(folderId);recordActivity('note',`Created a ${plan.days.length} day ${course} study plan`);renderPlannerPlan(plan);renderOrganization();toast('Your study plan is ready.')});
/* Progress */
function renderProgress(){const u=user();if(!u)return;const p=u.progress,avg=u.quizzes.length?Math.round(u.quizzes.reduce((a,b)=>a+b.score,0)/u.quizzes.length):null;$('#statNotes').textContent=u.notes.length;$('#statCards').textContent=p.cardsCompleted;$('#statKnown').textContent=`${p.cardsKnown} marked known`;$('#statQuiz').textContent=avg===null?'â€”':avg+'%';$('#statStreak').textContent=p.streak+(p.streak===1?' day':' days');$('#quizChart').innerHTML=u.quizzes.length?u.quizzes.slice(-7).map(q=>`<div class="chart-bar"><b>${q.score}%</b><i style="height:${q.score}%"></i><small>${escapeHTML(q.subject.slice(0,4))}</small></div>`).join(''):'<div class="empty-mini">Complete a quiz to see your scores here.</div>';$('#weakTopics').innerHTML=p.weakTopics.length?p.weakTopics.slice(-6).map(t=>`<div class="weak-item"><b>${escapeHTML(t)}</b><span>Review next</span></div>`).join(''):'<div class="empty-mini">Topics marked â€œNeed reviewâ€ will appear here.</div>';$('#subjectProgress').innerHTML=getSubjects().map(s=>{const score=subjectScore(s);return `<div class="progress-subject"><b>${escapeHTML(s)}</b><div class="progress-line"><i style="width:${score}%"></i></div><span>${score}%</span></div>`}).join('')}

async function init(){await Promise.all([loadCourses(),loadPlannerTemplates()]);if(currentUser===GUEST_SESSION)enterGuestMode();else if(currentUser&&db.users[currentUser])logIn(currentUser);else{localStorage.removeItem(SESSION_KEY);$('#landing').classList.add('active')}}
init();
